'use strict';
const paths={user:'M20 21v-2a7 7 0 0 0-14 0v2M16 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0',users:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2M15 3a4 4 0 0 1 0 8M22 21v-2a4 4 0 0 0-3-3.9M13 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0',layers:'m12 3 10 5-10 5L2 8l10-5ZM2 12l10 5 10-5M2 16l10 5 10-5',file:'M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8l-6-6Zm0 0v6h6M8 13h8M8 17h6',search:'m21 21-5-5M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',settings:'M4 7h16M4 17h16M8 4v6M16 14v6',plus:'M12 5v14M5 12h14',arrow:'M19 12H5m6-6-6 6 6 6',edit:'m16 3 5 5-12 12-6 1 1-6L16 3ZM14 5l5 5',building:'M3 21h18M5 21V5l7-3 7 3v16M9 8h1M14 8h1M9 12h1M14 12h1M10 21v-5h4v5',pin:'M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 1 1 16 0ZM15 10a3 3 0 1 1-6 0 3 3 0 0 1 6 0',check:'m5 12 4 4L19 6',eye:'M2 12s3-7 10-7 10 7 10 7-3 7-10 7S2 12 2 12ZM15 12a3 3 0 1 1-6 0 3 3 0 0 1 6 0',link:'m10 13 4-4M8 16l-2 2a4 4 0 0 1-6-6l4-4a4 4 0 0 1 6 0M16 8l2-2a4 4 0 0 1 6 6l-4 4a4 4 0 0 1-6 0',calendar:'M8 2v4M16 2v4M3 10h18M5 4h14a2 2 0 0 1 2 2v14a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V6a2 2 0 0 1 2-2',menu:'M4 6h16M4 12h16M4 18h16',sparkles:'m12 3 2.6 6.4L21 12l-6.4 2.6L12 21l-2.6-6.4L3 12l6.4-2.6L12 3ZM20 2v4m-2-2h4',book:'M3 3h6a4 4 0 0 1 3 2 4 4 0 0 1 3-2h6v17h-6a4 4 0 0 0-3 2 4 4 0 0 0-3-2H3V3Zm9 2v17'};
const icon=name=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.file}"/></svg>`;
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const $=id=>document.getElementById(id);
const storage={get(key,fallback=null){try{return JSON.parse(localStorage.getItem(key))??fallback;}catch{return fallback;}},set(key,value){try{localStorage.setItem(key,JSON.stringify(value));return true;}catch{return false;}},remove(key){try{localStorage.removeItem(key);}catch{}}};
let data={entities:[],users:[],articles:[],schema:{classes:{}}};
let personId=storage.get('ritou-person','石橋治樹');
let portfolioTab='activities',editor=null,profileDraft=null,filter='all',search='',saving=false;
const chipSpecs={targets:{cls:'Target',label:'対象となる地域・現場',placeholder:'地域名や施設名を入力'},issues:{cls:'Issue',label:'取り組む課題',placeholder:'困っていること・解決したいこと'},technologies:{cls:'Technology',label:'用いる技術・手法',placeholder:'通信技術、調査手法など'},resources:{cls:'Resource',label:'活用する設備・材料・知識',placeholder:'機器、材料、地域の資源など'},affiliations:{cls:'Laboratory',label:'所属',placeholder:'学校・研究室・組織の名前'},statuses:{cls:'Status',label:'立場',placeholder:'学生、教員など'},keywords:{cls:null,label:'研究キーワード',placeholder:'研究の関心やテーマ'},related_research:{cls:'Research',label:'この記事で取り上げる研究・活動',placeholder:'登録済みの研究・活動を検索',existingOnly:true},related_entities:{cls:'Any',label:'補足の関連項目',placeholder:'この記事独自の関連項目を検索',existingOnly:true}};
const entity=id=>data.entities.find(e=>e.id===id);
const literal=(e,p)=>e?.literals?.[p]?.[0]||'';
const title=e=>literal(e,'表示名')||literal(e,'タイトル')||e?.id||'';
const out=(e,p)=>e?.outgoing?.filter(x=>[].concat(p).includes(x.predicate)).map(x=>x.object_id)||[];
const uniq=values=>[...new Set(values.filter(Boolean))];
const split=value=>uniq(String(value||'').split(/[,、\n]/).map(x=>x.trim()).filter(Boolean));
const safeUrl=value=>/^https?:\/\//i.test(value||'')?value:'#';
const activityHref=id=>'#activity/'+encodeURIComponent(id);
const personHref=id=>'#person/'+encodeURIComponent(id);
const initial=id=>title(entity(id)).replace(/\s/g,'').slice(0,1)||'?';
function notify(message){$('toast').textContent=message;$('toast').hidden=false;clearTimeout(notify.timer);notify.timer=setTimeout(()=>$('toast').hidden=true,3500);}
async function request(url,payload){const response=await fetch(url,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});const result=await response.json();if(!response.ok)throw new Error(typeof result.detail==='string'?result.detail:'入力内容を確認してください');return result;}
async function load(){const response=await fetch('/api/data');if(!response.ok)throw new Error('データを読み込めませんでした');data=await response.json();if(!entity(personId))personId=data.users[0]?.id||'';const users=[...data.users].sort((a,b)=>title(a).localeCompare(title(b),'ja'));$('person-switch').innerHTML=users.map(p=>`<option value="${esc(p.id)}">${esc(title(p))}</option>`).join('');$('person-switch').value=personId;}
function paintIcons(root=document){root.querySelectorAll('[data-icon]').forEach(el=>el.innerHTML=icon(el.dataset.icon));}
function setPage(breadcrumb,html,nav='portfolio'){$('breadcrumb').innerHTML=`離島工学DB <span>/</span> ${esc(breadcrumb)}`;$('topbar-actions').innerHTML=nav==='articles'?`<a class="button small" href="#portfolio">${icon('user')}ポートフォリオへ</a>`:`<button class="button primary small" data-action="new-activity">${icon('plus')}研究・活動を追加</button>`;$('main').innerHTML=html;document.querySelectorAll('[data-nav]').forEach(a=>a.classList.toggle('active',a.dataset.nav===nav));document.querySelector('.sidebar').classList.remove('open');$('mobile-menu').setAttribute('aria-expanded','false');paintIcons($('main'));}
function participants(id){const members=new Map();for(const record of data.entities.filter(e=>e.types.includes('Participation')&&out(e,'活動').includes(id))){const name=out(record,'主体')[0];if(!name)continue;const actor=entity(name);const value=members.get(name)||{name,role:'',actor_class:actor?.types.find(t=>['User','Laboratory','ActorGroup'].includes(t))||'User'};value.role=uniq([...value.role.split('・'),literal(record,'役割')]).join('・');members.set(name,value);}for(const actor of data.entities.filter(e=>e.types.some(t=>['User','Laboratory','ActorGroup'].includes(t))&&out(e,['担当する','扱う']).includes(id))){if(!members.has(actor.id))members.set(actor.id,{name:actor.id,role:'担当',actor_class:actor.types.includes('User')?'User':actor.types.includes('Laboratory')?'Laboratory':'ActorGroup'});}return [...members.values()];}
function projectsFor(id){return data.entities.filter(e=>e.types.includes('Research')&&participants(e.id).some(p=>p.name===id));}
function projectCard(e,context=''){const people=participants(e.id);const issues=out(e,'解決を試みる');const techs=out(e,['用いる','扱う']).filter(id=>entity(id)?.types.includes('Technology'));return `<article class="panel project-card"><div class="card-topline"><span class="category-label">研究・活動</span><span class="fine">${esc(literal(e,'実施時期')||'')}</span></div><a class="project-title" href="${activityHref(e.id)}">${esc(title(e))}</a>${literal(e,'概要')?`<p class="card-summary">${esc(literal(e,'概要'))}</p>`:''}<div class="tags">${issues.slice(0,2).map(v=>`<span class="tag issue">${esc(title(entity(v))||v)}</span>`).join('')}${techs.slice(0,3).map(v=>`<span class="tag">${esc(title(entity(v))||v)}</span>`).join('')}</div><div class="card-footer"><div class="person-initials">${people.slice(0,4).map(p=>`<span title="${esc(title(entity(p.name)))}">${esc(initial(p.name))}</span>`).join('')}</div><span>${esc(context||people.map(p=>title(entity(p.name))||p.name).join('・')||'メンバー未登録')}</span><button class="button text small edit" data-action="edit-activity" data-id="${esc(e.id)}">${icon('edit')}編集</button></div></article>`;}
function prose(text){return String(text||'').split(/\n\s*\n/).map(p=>{const match=p.match(/^(#{1,3})\s+(.+)$/m);return match&&p.trim().startsWith('#')?`<h3>${esc(p.replace(/^#{1,3}\s+/,''))}</h3>`:`<p>${esc(p)}</p>`;}).join('');}
function empty(titleText,description,action='new-activity',button='研究・活動を追加'){return `<div class="empty"><div class="empty-icon">${icon('layers')}</div><h3>${esc(titleText)}</h3><p>${esc(description)}</p>${action?`<button class="button primary small" data-action="${action}">${icon('plus')}${esc(button)}</button>`:''}</div>`;}
function drafts(){const value=storage.get('ritou-activity-drafts:'+personId,{});const legacy=storage.get('ritou-activity-draft:'+personId);if(legacy){value[legacy.entity_id||'new']=legacy;storage.remove('ritou-activity-draft:'+personId);storage.set('ritou-activity-drafts:'+personId,value);}return value;}
function latestDraft(){return Object.values(drafts()).sort((a,b)=>(b._updated||0)-(a._updated||0))[0]||null;}
function deleteDraft(key){const all=drafts();delete all[key];storage.set('ritou-activity-drafts:'+personId,all);}
function draftBanner(){const draft=latestDraft();return draft?`<div class="draft-banner">${icon('file')}<div>書きかけの研究・活動があります<br><span class="fine">${esc(draft.title||'名称未入力')}</span></div><button class="button small" data-action="resume-draft">続きを書く</button><button class="icon-button" data-action="discard-draft" aria-label="下書きを削除">×</button></div>`:storage.get('ritou-discarded-draft:'+personId)?`<p class="fine" style="margin-bottom:15px"><button class="button text small" data-action="restore-draft">直前に削除した下書きを復元</button></p>`:'';}
function renderPortfolio(id=personId){const p=entity(id);if(!p)return setPage('ポートフォリオ',`<div class="page">${empty('まず研究者を登録してください','詳細編集から研究者を登録できます。',null)}</div>`);const mine=projectsFor(id);const arts=data.articles.filter(a=>a.authors.includes(id)||(a.record_subjects||[]).includes(id));const labs=out(p,'所属する');const tags=split(literal(p,'研究キーワード'));const myTechs=uniq(mine.flatMap(e=>out(e,['用いる','扱う']))).filter(k=>entity(k)?.types.includes('Technology'));const labmates=data.users.filter(u=>u.id!==id&&out(u,'所属する').some(l=>labs.includes(l)));const labProjects=uniq(labmates.flatMap(u=>projectsFor(u.id).map(e=>e.id))).filter(k=>!mine.some(e=>e.id===k)).map(entity);const editButton=`<button class="button small profile-edit" data-action="edit-profile" data-id="${esc(id)}">${icon('edit')}<span>プロフィールを編集</span></button>`;let content='';if(portfolioTab==='profile'){content=`<div class="panel content-block"><h2>プロフィール</h2><div class="prose">${prose(p.wiki_content)||'<p class="muted">自己紹介はまだ登録されていません。</p>'}</div><button class="button text small" data-action="edit-profile" data-id="${esc(id)}">${icon('edit')}自己紹介を編集</button></div>`;}else if(portfolioTab==='articles'){content=`<div class="section-heading"><h2>記事・記録 <span class="fine">${arts.length}件</span></h2><a class="button small" href="#activity-record/${encodeURIComponent(id)}">${icon('plus')}活動記録を書く</a></div><div class="stack">${arts.map(articleCard).join('')||empty('記事・記録はまだありません','研究に関するお知らせや実践の記録を蓄積できます。',null)}</div>`;}else{content=`<div class="section-heading"><h2>参加している研究・活動 <span class="fine">${mine.length}件</span></h2><button class="button text small" data-action="new-activity">${icon('plus')}追加する</button></div><div class="stack">${mine.map(e=>projectCard(e)).join('')||empty('取り組んでいることを、ひとつから。','名称と概要だけでも登録できます。課題や技術、関わる人は、あとから追加できます。')}</div>${labProjects.length?`<div class="lab-section"><div class="section-heading"><div><h2>所属組織の研究・活動</h2><p class="fine">${esc(labs.map(l=>title(entity(l))||l).join('・'))}のメンバーによる取り組み</p></div></div><div class="stack">${labProjects.map(e=>projectCard(e)).join('')}</div></div>`:''}`;}
setPage('ポートフォリオ',`<div class="page"><div class="page-heading"><div><div class="eyebrow">MY PORTFOLIO</div><h1>研究と実践のポートフォリオ</h1><p>日々の取り組みを記録し、地域の知とつなげる。</p></div></div>${id===personId?draftBanner():''}<section class="panel profile-header"><div class="profile-stripe"></div><div class="profile-body"><div class="avatar" aria-hidden="true">${esc(initial(id))}</div><div class="profile-title"><h2 class="profile-name">${esc(title(p))}</h2><div class="profile-meta">${labs.map(l=>`<a href="#entity/${encodeURIComponent(l)}">${icon('building')}${esc(title(entity(l))||l)}</a>`).join('')}<span>${esc(literal(p,'肩書')||out(p,'である').map(v=>title(entity(v))||v).join('・'))}</span></div><p class="profile-intro">${esc(literal(p,'概要')||'研究・実践の取り組みを、ここにまとめていきます。')}</p><div class="profile-counts"><div class="count">${mine.length}<small>研究・活動</small></div><div class="count">${arts.length}<small>記事・記録</small></div><div class="count">${myTechs.length}<small>研究で用いる技術</small></div></div></div>${editButton}</div><div class="tabs" role="tablist" aria-label="ポートフォリオの表示"><button role="tab" aria-selected="${portfolioTab==='activities'}" class="${portfolioTab==='activities'?'active':''}" data-action="portfolio-tab" data-value="activities">研究・活動<span class="num">${mine.length}</span></button><button role="tab" aria-selected="${portfolioTab==='profile'}" class="${portfolioTab==='profile'?'active':''}" data-action="portfolio-tab" data-value="profile">プロフィール</button><button role="tab" aria-selected="${portfolioTab==='articles'}" class="${portfolioTab==='articles'?'active':''}" data-action="portfolio-tab" data-value="articles">記事・記録<span class="num">${arts.length}</span></button></div></section><div class="portfolio-columns"><div>${content}</div><aside class="portfolio-side"><div class="panel aside-card"><h3>研究キーワード</h3>${tags.length?`<div class="tags">${tags.map(t=>`<a class="tag" href="#activities?q=${encodeURIComponent(t)}" aria-label="${esc(t)}で研究・活動を検索">${esc(t)}</a>`).join('')}</div>`:`<p>関心のあるテーマや研究分野を登録できます。</p><button class="button text small" data-action="edit-profile" data-id="${esc(id)}">${icon('plus')}キーワードを追加</button>`}<div class="divider"></div><h3>関連リンク</h3>${out(p,'外部リンク').map(l=>`<a class="quiet-link" href="${esc(safeUrl(l))}" target="_blank" rel="noopener noreferrer">${esc(l.replace(/^https?:\/\//,''))} ↗</a>`).join('')||'<p>まだ登録されていません。</p>'}</div><div class="panel aside-card"><h3>小さな記録から、知識へ。</h3><p>最初からすべて埋めなくても大丈夫です。活動を書きながら、同じ課題や技術に取り組む人との接点を増やしていきましょう。</p><a class="quiet-link" href="#explore">地域・課題から探す →</a></div></aside></div></div>`);}
function articleResearchIds(a){return a.related_research||a.related_entities.filter(id=>entity(id)?.types.includes('Research'));}
function articleSupplementIds(a){return a.additional_related||a.related_entities.filter(id=>!entity(id)?.types.includes('Research'));}
function articleImage(a,classes=''){const src=/^https?:\/\//i.test(a.thumbnail_url||'')||/^\/media\/article-thumbnails\/[a-f0-9]{64}\.webp$/.test(a.thumbnail_url||'')?a.thumbnail_url:'';return src?`<img class="article-thumbnail ${classes}" src="${esc(src)}" alt="${esc(a.thumbnail_alt||'')}" loading="lazy">`:'';}
function articleKindLabel(kind){return {'ニュース・発表':'ニュース・お知らせ','研究・実践記事':'研究ノート'}[kind]||kind;}
function isNewsArticle(a){return ['ニュース・発表','ニュース・お知らせ','ニュース'].includes(a.article_type);}
function articleCard(a){const research=articleResearchIds(a);return `<article class="panel article-row ${a.thumbnail_url?'has-thumbnail':''}">${a.thumbnail_url?`<a class="article-thumbnail-link" tabindex="-1" aria-hidden="true" href="#article/${encodeURIComponent(a.id)}">${articleImage(a)}</a>`:''}<div class="article-card-copy"><div class="card-topline"><span class="category-label">${esc(articleKindLabel(a.article_type))}</span><time class="fine">${esc(a.date)}</time></div><h3><a class="article-title" href="#article/${encodeURIComponent(a.id)}">${esc(a.title)}</a></h3><p class="card-summary">${esc(markdownPlainText(a.content).slice(0,160))}</p>${research.length?`<div class="article-research-links">${research.map(id=>`<a href="${activityHref(id)}">${icon('layers')}${esc(title(entity(id))||id)} →</a>`).join('')}</div>`:''}<div class="card-footer"><span>著者</span>${a.authors.map(id=>`<a class="article-author" href="${personHref(id)}">${esc(title(entity(id))||id)}</a>`).join('・')||'<span>未登録</span>'}<a class="article-read" href="#article/${encodeURIComponent(a.id)}">記事を読む →</a></div></div></article>`;}

function renderList(view){const kinds={activities:{heading:'研究・活動',caption:'地域で生まれた研究と実践を見つける。',type:'Research',eyebrow:'PROJECTS'},people:{heading:'研究者・実践者',caption:'地域の課題に向き合う人と、その取り組み。',type:'User',eyebrow:'PEOPLE'},articles:{heading:'ニュース・お知らせ',caption:'研究や地域での活動から届いたお知らせ。',eyebrow:'NEWS'},explore:{heading:'地域・課題から探す',caption:'気になる課題や地域から、取り組みへの入口を探す。',eyebrow:'EXPLORE'}};const info=kinds[view];setPage(info.heading,`<div class="page"><div class="page-heading"><div><div class="eyebrow">${info.eyebrow}</div><h1>${info.heading}</h1><p>${info.caption}</p></div>${view==='articles'?`<a class="button small" href="#article-new">${icon('plus')}ニュースを書く</a>`:''}${view==='activities'?`<button class="button primary" data-action="new-activity">${icon('plus')}追加する</button>`:''}</div><div class="searchbar">${icon('search')}<input id="list-search" type="search" aria-label="${info.heading}を検索" placeholder="${view==='activities'?'名称・課題・技術などで検索':'名前やキーワードで検索'}" value="${esc(search)}"></div>${view==='explore'?`<div class="filters">${[['all','すべて'],['Target','地域・現場'],['Issue','地域課題'],['Technology','技術・手法'],['Resource','資源']].map(([v,l])=>`<button class="filter ${filter===v?'active':''}" data-action="filter" data-value="${v}">${l}</button>`).join('')}</div>`:''}<div id="list-results"></div></div>`,view);renderListResults(view);}
function renderListResults(view){const q=search.toLowerCase();let items=view==='articles'?data.articles.filter(isNewsArticle).filter(a=>(a.title+' '+a.content+' '+[...a.authors,...a.related_entities,...(a.inherited_entities||[]),...(a.record_subjects||[])].map(id=>title(entity(id))||id).join(' ')).toLowerCase().includes(q)):data.entities.filter(e=>view==='activities'?e.types.includes('Research'):view==='people'?e.types.includes('User'):e.types.some(t=>['Target','Issue','Technology','Resource'].includes(t))&&(filter==='all'||e.types.includes(filter))).filter(e=>(title(e)+' '+literal(e,'概要')+' '+out(e,['対象とする','解決を試みる','用いる','扱う','活用する']).map(id=>id+' '+title(entity(id))).join(' ')).toLowerCase().includes(q));let html=view==='activities'?`<div class="stack">${items.map(e=>projectCard(e)).join('')}</div>`:view==='articles'?`<div class="article-grid">${items.map(articleCard).join('')}</div>`:view==='people'?`<div class="people-grid">${items.map(p=>`<a class="panel person-card" href="${personHref(p.id)}"><div class="avatar small">${esc(initial(p.id))}</div><div><h3>${esc(title(p))}</h3><p>${esc(out(p,'所属する').map(v=>title(entity(v))||v).join('・'))}</p><p>${projectsFor(p.id).length}件の研究・活動</p></div></a>`).join('')}</div>`:`<div class="entity-grid">${items.map(e=>`<a class="panel entity-card" href="#entity/${encodeURIComponent(e.id)}"><p class="eyebrow">${esc(e.type_info.short)}</p><h3>${esc(title(e))}</h3><p>${esc(literal(e,'概要'))}</p></a>`).join('')}</div>`;$('list-results').innerHTML=`<p class="result-count">${items.length}件</p>${items.length?html:empty('該当する情報がありません','検索する言葉を変えるか、新しい取り組みを登録してください。',view==='activities'?'new-activity':null)}`;}
function portfolioRecordSection(id){const records=data.articles.filter(a=>a.article_type==='活動記録'&&(a.record_subjects||[]).includes(id));return `<section class="panel content-block lab-section"><div class="section-heading"><h2>活動記録</h2><a class="button small" href="#activity-record/${encodeURIComponent(id)}">${icon('plus')}活動記録を書く</a></div><div class="stack">${records.map(articleCard).join('')||'<p class="fine">この組織・集団の活動記録はまだありません。</p>'}</div></section>`;}
function organizationAffiliationSection(e){
  const parents=out(e,'所属する').map(entity).filter(Boolean);
  const members=data.entities.filter(item=>out(item,'所属する').includes(e.id));
  const links=items=>items.map(item=>`<a class="tag" href="#entity/${encodeURIComponent(item.id)}">${esc(title(item))}</a>`).join('');
  const groups=[['所属先の組織',parents,'所属先は未設定です。'],['所属する組織',members.filter(item=>item.types.includes('Laboratory')),'所属する組織はまだありません。'],['所属メンバー',members.filter(item=>item.types.includes('User')),'所属メンバーはまだありません。']];
  return `<section class="organization-affiliations"><div class="section-heading"><h2>所属関係</h2></div><div class="affiliation-groups">${groups.map(([label,items,emptyText])=>`<div class="affiliation-group"><h3>${label}</h3>${items.length?`<div class="tags">${links(items)}</div>`:`<p class="fine">${emptyText}</p>`}</div>`).join('')}</div></section>`;
}
function openOrganizationAffiliations(id){
  const e=entity(id);if(!e?.types.includes('Laboratory'))return;
  profileDraft={entity_id:id,affiliations:out(e,'所属する'),_pending:{}};
  $('profile-dialog-content').innerHTML=`<form id="organization-affiliations-form"><div class="dialog-header"><h2 id="profile-dialog-title">所属先を編集</h2><button type="button" class="icon-button" data-action="close-profile" aria-label="閉じる">×</button></div><div class="dialog-body"><div id="organization-affiliations-error" class="form-error" hidden role="alert"></div><p>${esc(title(e))}が所属する組織を選んでください。</p>${chipField('affiliations',profileDraft)}<p class="hint">複数の所属先を登録できます。新しい組織名も入力できます。</p></div><div class="dialog-actions"><button class="button" type="button" data-action="close-profile">キャンセル</button><button class="button primary" type="submit" id="save-organization-affiliations">保存する</button></div></form>`;
  $('profile-dialog').showModal();
}
async function saveOrganizationAffiliations(event){
  event.preventDefault();
  let affiliations;
  const button=$('save-organization-affiliations');button.disabled=true;
  try{
    affiliations=organizationAffiliations(profileDraft);
    await request('/api/entity',{entity_id:profileDraft.entity_id,entity_class:'Laboratory',relations:affiliations.map(id=>({predicate:'所属する',object:id})),replace_predicates:['所属する']});
    $('profile-dialog').close();await load();route();notify('所属先を保存しました');
  }catch(error){$('organization-affiliations-error').textContent=error.message;$('organization-affiliations-error').hidden=false;button.disabled=false;}
}
function renderOrganizations(){
  const q=search.toLowerCase();
  const organizations=data.entities.filter(e=>e.types.includes('Laboratory')&&(title(e)+' '+literal(e,'概要')+' '+out(e,'所属する').map(id=>title(entity(id))||id).join(' ')).toLowerCase().includes(q));
  setPage('組織・研究室',`<div class="page"><div class="page-heading"><div><p class="eyebrow">ORGANIZATIONS</p><h1>組織・研究室</h1><p>学校・研究室・地域団体などの情報と、所属関係をまとめます。</p></div><button class="button primary" data-action="new-organization">${icon('plus')}組織を追加</button></div><div class="searchbar">${icon('search')}<input id="organization-search" type="text" aria-label="組織を検索" placeholder="組織名や所属先で検索" value="${esc(search)}"></div><div id="organization-results"><p class="result-count">${organizations.length}件</p><div class="entity-grid">${organizations.map(e=>`<a class="panel entity-card" href="#entity/${encodeURIComponent(e.id)}"><p class="eyebrow">組織・研究室</p><h3>${esc(title(e))}</h3><p class="fine">${esc(out(e,'所属する').map(id=>title(entity(id))||id).join('・'))}</p></a>`).join('')}</div>${organizations.length?'':empty('組織が見つかりません','新しい組織は「組織を追加」から登録できます。',null)}</div></div>`,'organizations');
}
function organizationSummary(e){return uniq([literal(e,'概要').trim(),(e?.wiki_content||'').trim()]).join('\n\n');}
function renderOrganization(e){
  const projects=projectsFor(e.id);
  setPage('組織・研究室',`<div class="page"><a class="back-link" href="#organizations">${icon('arrow')}組織一覧に戻る</a><section class="panel detail-header"><div class="detail-heading"><p class="eyebrow">組織・研究室</p><div class="detail-actions">${aiEntryLink(e.id,'この組織についてAIに聞く')}<button class="button small" data-action="edit-organization" data-id="${esc(e.id)}">${icon('edit')}組織情報を編集</button></div></div><h1>${esc(title(e))}</h1><div class="prose markdown-body organization-summary">${articleMarkdown(organizationSummary(e))}</div>${out(e,'外部リンク').length?`<div class="organization-links"><h2>関連リンク</h2>${out(e,'外部リンク').map(url=>`<a class="quiet-link" href="${esc(safeUrl(url))}" target="_blank" rel="noopener noreferrer">${esc(url)} ↗</a>`).join('')}</div>`:''}${organizationAffiliationSection(e)}</section><div class="section-heading lab-section"><h2>参加している研究・活動</h2></div><div class="stack">${projects.map(p=>projectCard(p)).join('')||empty('参加している研究・活動はまだありません','研究・活動のメンバーにこの組織を追加すると表示されます。',null)}</div>${portfolioRecordSection(e.id)}</div>`,'organizations');
}
function openOrganizationEditor(id=''){
  const e=id?entity(id):null;if(id&&!e?.types.includes('Laboratory'))return;
  profileDraft={entity_id:id,name:e?title(e):'',summary:organizationSummary(e),description:'',affiliations:out(e,'所属する'),external_links:out(e,'外部リンク'),_pending:{}};
  const p=profileDraft;
  $('profile-dialog-content').innerHTML=`<form id="organization-form"><div class="dialog-header"><h2 id="profile-dialog-title">${id?'組織情報を編集':'組織を追加'}</h2><button type="button" class="icon-button" data-action="close-profile" aria-label="閉じる">×</button></div><div class="dialog-body"><div id="organization-error" class="form-error" hidden role="alert"></div><div class="field"><label for="organization-name">組織名<span class="required">必須</span></label><input id="organization-name" data-organization-key="name" value="${esc(p.name)}" required maxlength="300" placeholder="学校・研究室・団体の名前"></div><div class="field"><label for="organization-summary">概要 <span class="optional">Markdown対応</span></label><textarea id="organization-summary" data-organization-key="summary" rows="8">${esc(p.summary)}</textarea><p class="hint">見出し（##）、箇条書き（-）、太字（**文字**）、リンク・画像・表などを使えます。</p><details class="organization-summary-preview"><summary>プレビュー</summary><div id="organization-summary-preview" class="prose markdown-body markdown-edit-preview">${articleMarkdown(p.summary)}</div></details></div>${chipField('affiliations',p)}<p class="hint">この組織が所属する学校・学科・団体などを登録できます。</p><div class="field"><label for="organization-links">関連リンク（1行に1件）</label><textarea id="organization-links" data-organization-key="external_links" rows="3" placeholder="https://...">${esc(p.external_links.join('\n'))}</textarea></div></div><div class="dialog-actions"><button class="button" type="button" data-action="close-profile">キャンセル</button><button class="button primary" type="submit" id="save-organization">保存する</button></div></form>`;
  $('profile-dialog').showModal();
}
async function saveOrganization(event){
  event.preventDefault();const p={...profileDraft};
  document.querySelectorAll('#organization-form [data-organization-key]').forEach(input=>p[input.dataset.organizationKey]=input.dataset.organizationKey==='external_links'?input.value.split('\n').map(v=>v.trim()).filter(Boolean):input.value);
  delete p._pending;
  const button=$('save-organization');button.disabled=true;$('organization-error').hidden=true;
  try{p.affiliations=organizationAffiliations(p);const result=await request('/api/portfolio/organization',p);$('profile-dialog').close();await load();location.hash='#entity/'+encodeURIComponent(result.entity_id);route();notify('組織情報を保存しました');}
  catch(error){$('organization-error').textContent=error.message;$('organization-error').hidden=false;button.disabled=false;}
}
function renderEntity(id){const e=entity(id);if(!e)return notFound();if(e.types.includes('Target'))return renderPlace(id);if(e.types.includes('Issue')){location.hash='#issue/'+encodeURIComponent(id);return;}if(e.types.includes('Research'))return renderActivity(id);if(e.types.includes('User'))return renderPortfolio(id);if(e.types.includes('Laboratory'))return renderOrganization(e);if(e.types.some(t=>['Source','Evidence','Result','Goal','Participation'].includes(t)))return renderKnowledgeRecord(e);const projects=data.entities.filter(p=>p.types.includes('Research')&&p.outgoing.some(o=>o.object_id===id));setPage('知識を探す',`<div class="page"><a class="back-link" href="#explore">${icon('arrow')}地域・課題から探す</a><section class="panel detail-header"><div class="detail-heading"><p class="eyebrow">${esc(e.type_info.short)}</p><div class="detail-actions">${aiEntryLink(id,'この項目についてAIに聞く')}</div></div><h1>${esc(title(e))}</h1><p class="description">${esc(literal(e,'概要'))}</p>${e.wiki_content?`<div class="prose">${prose(e.wiki_content)}</div>`:''}</section><div class="section-heading lab-section"><h2>関連する研究・活動</h2></div><div class="stack">${projects.map(p=>projectCard(p)).join('')||empty('関連する取り組みはまだありません','研究・活動の登録時に、この項目を選択すると関連付けられます。',null)}</div>${e.types.some(t=>['Laboratory','ActorGroup'].includes(t))?portfolioRecordSection(id):''}</div>`,'explore');}
function articlePageContext(a){
  if(a.article_type==='研究・実践記事'){
    const project=articleResearchIds(a)[0];
    return {nav:'activities',breadcrumb:'研究・活動 / 研究ノート',href:project?activityHref(project):'#activities',label:'研究・活動に戻る'};
  }
  if(a.article_type==='活動記録'){
    const owner=(a.record_subjects||[])[0];
    return {nav:'portfolio',breadcrumb:'ポートフォリオ / 活動記録',href:owner?'#entity/'+encodeURIComponent(owner):'#portfolio',label:'ポートフォリオに戻る'};
  }
  return {nav:'articles',breadcrumb:'ニュース・お知らせ',href:'#articles',label:'ニュース・お知らせの一覧へ'};
}
function renderArticle(id){const a=data.articles.find(a=>a.id===id);if(!a)return notFound();const pageContext=articlePageContext(a);const research=articleResearchIds(a);const extras=articleSupplementIds(a);setPage(pageContext.breadcrumb,`<div class="page"><a class="back-link" href="${pageContext.href}">${icon('arrow')}${pageContext.label}</a><article class="panel content-block"><div class="card-topline detail-heading"><p class="fine">${esc(a.date)} · ${esc(articleKindLabel(a.article_type))}${a.modified_at?`<br>更新：${esc(a.modified_at.replace('T',' ').slice(0,16))}`:''}</p><div class="detail-actions">${aiEntryLink(a.id,'この記事についてAIに聞く')}${data.article_editing_enabled!==false?`<a class="button small" href="#article-edit/${encodeURIComponent(a.id)}">${icon('edit')}記事を編集 <span class="temporary-label">一時対応</span></a>`:''}</div></div><h1>${esc(a.title)}</h1><div class="article-byline"><span>著者</span>${a.authors.map(id=>`<a class="article-author" href="${personHref(id)}">${esc(title(entity(id))||id)}</a>`).join('・')||'<span>未登録</span>'}</div>${(a.record_subjects||[]).length?`<p class="hint">活動記録の記録先：${a.record_subjects.map(id=>`<a class="article-author" href="#entity/${encodeURIComponent(id)}">${esc(title(entity(id))||id)}</a>`).join('・')}</p>`:''}${articleImage(a,'article-cover')}<div class="prose markdown-body lab-section" id="article-reader-content">${articleMarkdown(a.content)}</div>${researchArticleTools(a)}${research.length?`<section class="article-related"><h2>この記事の研究・活動</h2><div class="stack">${research.map(id=>{const project=entity(id);return `<a class="article-research-card" href="${activityHref(id)}"><span>${icon('layers')}</span><div><h3>${esc(title(project)||id)}</h3>${literal(project,'概要')?`<p>${esc(literal(project,'概要'))}</p>`:''}<small>研究の詳細・メンバー・課題・技術を見る →</small></div></a>`;}).join('')}</div></section>`:''}${extras.length?`<section class="article-related"><h2>補足の関連項目</h2><div class="tags">${extras.map(id=>`<a class="tag" href="#entity/${encodeURIComponent(id)}">${esc(title(entity(id))||id)} →</a>`).join('')}</div></section>`:''}${(a.external_links||[]).length?`<section class="article-related"><h2>関連リンク</h2>${a.external_links.map(url=>`<a class="quiet-link" href="${esc(safeUrl(url))}" target="_blank" rel="noopener noreferrer">${esc(url)} ↗</a>`).join('')}</section>`:''}</article></div>`,pageContext.nav);}

function notFound(){setPage('見つかりません',`<div class="page">${empty('情報が見つかりませんでした','一覧からもう一度選択してください。',null)}<a class="button" href="#portfolio">ポートフォリオへ</a></div>`);}

// 入力中の項目はローカルの下書きとして保存し、明示的な保存時だけDBに反映する。
function activityModel(id){const e=entity(id);return e?{entity_id:e.id,title:title(e),summary:literal(e,'概要'),description:e.wiki_content||'',period:literal(e,'実施時期'),goal:out(e,'目指す').includes(e.id+'_portfolio_goal')?literal(entity(e.id+'_portfolio_goal'),'概要'):'',targets:out(e,'対象とする'),issues:out(e,'解決を試みる'),technologies:uniq(out(e,['用いる','扱う'])).filter(v=>entity(v)?.types.includes('Technology')),resources:out(e,'活用する'),participants:participants(e.id),external_links:out(e,'外部リンク'),_pending:{}}:{entity_id:'',title:'',summary:'',description:'',period:'',goal:'',targets:[],issues:[],technologies:[],resources:[],participants:personId?[{name:personId,role:'担当',actor_class:'User'}]:[],external_links:[],_pending:{}};}
function startEditor(id='',resume=false){const saved=resume?latestDraft():drafts()[id||'new'];if(!resume&&saved&&(saved.entity_id||'')===id&&(!id||entity(id))){resume=true;}editor=resume&&saved?saved:activityModel(id);editor._pending=editor._pending||{};location.hash='#editor';renderEditor();}
function chipMarkup(key,model){const spec=chipSpecs[key];const list=model[key]||[];const candidates=chipCandidates(key,model).filter(e=>!list.includes(e.id)).slice(0,4);return `<div class="chip-entry" data-chip-area="${key}"><div class="chip-box"><span class="chip-selected" style="display:contents">${list.map((value,i)=>`<span class="selected-chip">${esc(title(entity(value))||value)}${key==='related_research'&&['research','news'].includes(model._entry_point)&&model._context_id===value?'<span class="fine">記録先</span>':`<button type="button" data-action="remove-chip" data-field="${key}" data-index="${i}" aria-label="${esc(value)}を外す">×</button>`}</span>`).join('')}</span><input id="chip-${key}" data-chip-input="${key}" type="text" autocomplete="off" role="combobox" aria-expanded="false" aria-autocomplete="list" aria-controls="suggest-${key}" aria-label="${spec.label}を追加" placeholder="${list.length?'追加する…':spec.placeholder}" value="${esc(model._pending?.[key]||'')}"></div><div class="suggestions" id="suggest-${key}" role="listbox" hidden></div></div>${candidates.length?`<div class="examples">${candidates.map(e=>`<button type="button" class="example-chip" data-action="add-chip" data-field="${key}" data-value="${esc(e.id)}">＋ ${esc(title(e))}</button>`).join('')}</div>`:''}`;}
function chipField(key,model){return `<div class="field"><label for="chip-${key}">${chipSpecs[key].label}</label><div id="chip-wrap-${key}">${chipMarkup(key,model)}</div><p class="hint">入力してEnterで追加。登録済みの候補からも選べます。</p></div>`;}
function memberMarkup(m,index){return `<div class="member-inputs" data-member="${index}"><input data-member-key="name" value="${esc(m.name)}" list="member-options" aria-label="メンバー${index+1}の名前" placeholder="名前・組織名"><select class="actor-class" data-member-key="actor_class" aria-label="メンバー${index+1}の種類">${[['User','個人'],['Laboratory','組織'],['ActorGroup','集団']].map(([v,t])=>`<option value="${v}" ${m.actor_class===v?'selected':''}>${t}</option>`).join('')}</select><input data-member-key="role" value="${esc(m.role)}" list="role-options" aria-label="メンバー${index+1}の役割" placeholder="役割"><button class="icon-button" type="button" data-action="remove-member" data-index="${index}" aria-label="メンバー${index+1}を外す">×</button></div>`;}
function renderEditor(){if(!editor){editor=latestDraft()||activityModel('');editor._pending=editor._pending||{};}const e=editor;setPage(e.entity_id?'研究・活動を編集':'研究・活動を追加',`<div class="page editor-page"><div class="editor-heading"><a class="back-link" href="${e.entity_id?activityHref(e.entity_id):'#portfolio'}">${icon('arrow')}${e.entity_id?'研究・活動に戻る':'ポートフォリオに戻る'}</a><div class="eyebrow">RECORD YOUR PRACTICE</div><h1>${e.entity_id?'研究・活動を編集':'新しい研究・活動を記録する'}</h1><p class="fine">まずは名称と概要から。詳しい情報は、あとから書き足せます。</p></div><div class="editor-layout"><form id="activity-form" class="editor-form"><div id="activity-error" class="form-error" role="alert" hidden></div><section class="panel form-section"><div class="section-title"><span class="section-number">01</span><h2>どんな取り組みですか？</h2></div><div class="field"><label for="activity-title">研究・活動の名称<span class="required">必須</span></label><input id="activity-title" data-key="title" required maxlength="300" value="${esc(e.title)}" placeholder="取り組みを表す名前をつけてください"></div><div class="field"><label for="activity-summary">ひとことで伝えると<span class="field-action" id="summary-count">${e.summary.length}文字</span></label><textarea id="activity-summary" data-key="summary" rows="3" placeholder="誰の、どんな課題に、何を使って取り組んでいますか？">${esc(e.summary)}</textarea><p class="hint">研究を知らない人にも伝わるように、2〜3文で。空欄のままでも保存できます。</p></div><div class="field"><label for="activity-period">取り組んでいる時期</label><input id="activity-period" data-key="period" value="${esc(e.period)}" placeholder="例：2026年度 ／ 2025年4月〜現在"><p class="hint">まだ決まっていなければ、空欄で大丈夫です。</p></div></section><section class="panel form-section"><div class="section-title"><span class="section-number">02</span><h2>どこで、何に取り組みますか？</h2><span class="optional">任意</span></div>${chipField('targets',e)}${chipField('issues',e)}</section><section class="panel form-section"><div class="section-title"><span class="section-number">03</span><h2>どんな方法・資源を使いますか？</h2><span class="optional">任意</span></div>${chipField('technologies',e)}${chipField('resources',e)}<p class="hint">技術・手法には「進め方」、資源には「活用するもの」を記録します。</p></section><section class="panel form-section"><div class="section-title"><span class="section-number">04</span><h2>誰と取り組みますか？</h2><span class="optional">任意</span></div><div id="member-rows">${e.participants.map(memberMarkup).join('')}</div><datalist id="member-options">${data.entities.filter(e=>e.types.some(t=>['User','Laboratory','ActorGroup'].includes(t))).map(e=>`<option value="${esc(e.id)}">${esc(title(e))}</option>`).join('')}</datalist><datalist id="role-options"><option>担当</option><option>指導</option><option>協力</option><option>運営</option><option>講師</option><option>調査</option></datalist><button type="button" class="add-member" data-action="add-member">＋ メンバー・協力組織を追加</button><p class="hint">人や組織と、活動の中での役割を記録します。新しい名前もそのまま追加できます。</p></section><section class="panel form-section"><details ${e.goal||e.description||e.external_links.length?'open':''}><summary>${icon('file')}もう少し詳しく書く<span class="optional">任意</span></summary><div class="field"><label for="activity-description">研究の紹介 <span class="optional">Markdown・構成は自由</span></label><p class="hint activity-overview-hint">好きな見出しや順番で、文章・箇条書き・画像・表を使って紹介できます。短いメモからでも大丈夫です。</p><div class="markdown-editor-tabs" role="tablist" aria-label="研究紹介の表示"><button type="button" id="activity-overview-write-tab" role="tab" aria-selected="true" aria-controls="activity-overview-write-pane" data-overview-view="write">書く</button><button type="button" id="activity-overview-preview-tab" role="tab" aria-selected="false" aria-controls="activity-overview-preview" data-overview-view="preview">プレビュー</button><span>Markdown</span></div><div id="activity-overview-write-pane" role="tabpanel" aria-labelledby="activity-overview-write-tab"><div class="markdown-tools" role="group" aria-label="研究紹介の書式">${[['heading','見出し'],['bold','太字'],['list','箇条書き'],['link','リンク'],['image','画像'],['table','表'],['code','コード']].map(([format,label])=>`<button type="button" data-overview-format="${format}">${label}</button>`).join('')}<button type="button" data-overview-related aria-expanded="false" aria-controls="activity-overview-related">関連項目へのリンク</button></div><div id="activity-overview-related" class="activity-overview-related" hidden></div><textarea id="activity-description" data-key="description" rows="14" placeholder="伝えたいことを、自由な構成で書いてください。

## 見出し
本文や **強調**、箇条書き、画像、表などが使えます。">${esc(e.description)}</textarea></div><div id="activity-overview-preview" class="prose markdown-body markdown-edit-preview activity-overview-preview" role="tabpanel" aria-labelledby="activity-overview-preview-tab" hidden></div><details class="markdown-guide"><summary>Markdownの書き方を見る</summary><p>見出し：<code>## 見出し</code> ／ 強調：<code>**太字**</code> ／ 箇条書き：<code>- 項目</code><br>リンク：<code>[文字](URL)</code> ／ 画像：<code>![説明](画像のURL)</code><br>表は上の「表」ボタンでひな型を挿入できます。</p></details></div><details class="activity-structured-goal"><summary>目標を関連情報として管理する <span class="optional">任意</span></summary><p class="hint">本文とは別に、目標を独立した関連情報として残したい場合だけ入力します。既存の目標もここで保持します。</p><div class="field"><label for="activity-goal">関連付ける目標</label><textarea id="activity-goal" data-key="goal" rows="3" placeholder="必要な場合だけ、関連付ける目標を記入">${esc(e.goal)}</textarea></div></details><div class="field"><label for="activity-links">関連リンク</label><textarea id="activity-links" data-key="external_links" rows="2" placeholder="https://...（1行に1件）">${esc(e.external_links.join('\n'))}</textarea><p class="hint">研究紹介ページ、GitHub、報告資料など。リンクだけで記述の根拠が確認済みになることはありません。</p></div></details></section></form><aside class="editor-aside"><p class="preview-label">${icon('eye')}ポートフォリオでの見え方</p><div id="live-preview"></div><p class="preview-help">入力内容は、保存するまでこのブラウザの下書きに残ります。<br>名称だけでも登録できます。</p><div class="panel aside-card"><h3>書いたあとから、整理する</h3>${e.entity_id?`<p>考察や試したことは記事に残せます。実績・評価や資料は、必要になったときに整理できます。</p><a class="quiet-link" href="${activityHref(e.entity_id)}">研究ページへ →</a>`:'<p>保存後の研究ページから記事を書き、必要な部分を実績・評価として整理できます。</p>'}</div></aside></div></div><div class="savebar"><span class="savebar-state" id="draft-state">${icon('check')}このブラウザに下書きを保存</span><div class="savebar-actions"><button class="button" type="button" data-action="preview-activity">${icon('eye')}プレビュー</button><button class="button primary" id="save-activity" type="submit" form="activity-form">保存して反映する ${icon('check')}</button></div></div>`,'activities');updatePreview();}
function currentChipModel(){return $('profile-dialog').open?profileDraft:$('article-form')?articleDraft:editor;}
function invalidOrganizationAffiliation(value,model){
  if(!model||(!Object.hasOwn(model,'name')&&!entity(model.entity_id)?.types.includes('Laboratory')))return false;
  const clean=String(value).trim().replace(/^:/,'');
  const name=($('organization-name')?.value||model.name||'').trim();
  if(clean===model.entity_id||(name&&clean===name))return true;
  const pending=data.entities.filter(e=>e.types.includes('Laboratory')&&(e.id===clean||title(e)===clean)).map(e=>e.id);
  const visited=new Set();
  while(pending.length){const id=pending.pop();if(id===model.entity_id)return true;if(visited.has(id))continue;visited.add(id);pending.push(...out(entity(id),'所属する'));}
  return false;
}
function organizationAffiliations(model){
  const values=uniq([...model.affiliations,...split($('chip-affiliations')?.value||'')]);
  if(values.some(value=>invalidOrganizationAffiliation(value,model)))throw new Error('自分自身や下位の組織は所属先に指定できません');
  return uniq(values.map(value=>{const clean=value.trim().replace(/^:/,'');return data.entities.find(e=>e.types.includes('Laboratory')&&(e.id===clean||title(e)===clean))?.id||clean;}));
}
function chipCandidates(key,model=currentChipModel()){const spec=chipSpecs[key];const candidates= spec.cls==='Any'?data.entities.filter(e=>!e.is_external&&e.types.some(t=>['Target','Issue','Technology','Resource','User','Laboratory','ActorGroup'].includes(t))):spec.cls?data.entities.filter(e=>e.types.includes(spec.cls)):[];return key==='affiliations'?candidates.filter(e=>!invalidOrganizationAffiliation(e.id,model)):candidates;}
function refreshChips(key){const model=currentChipModel();$('chip-wrap-'+key).innerHTML=chipMarkup(key,model);const input=$('chip-'+key);input.focus();suggest(key,input.value);persist();}
function addChips(key,value){const model=currentChipModel();const values=split(value);if(!values.length)return;if(key==='affiliations'&&values.some(v=>invalidOrganizationAffiliation(v,model))){notify('自分自身や下位の組織は所属先に指定できません');return;}const spec=chipSpecs[key];const normalized=values.map(v=>{const found=chipCandidates(key).find(e=>e.id===v||title(e)===v);return found?.id||(spec.existingOnly?'':v);});model[key]=uniq([...(model[key]||[]),...normalized.filter(Boolean)]);model._pending[key]='';refreshChips(key);}
function suggest(key,value){const area=$('suggest-'+key);if(!area)return;const spec=chipSpecs[key];const selected=currentChipModel()[key]||[];const matches=chipCandidates(key).filter(e=>!selected.includes(e.id)&&(title(e)+' '+e.id).toLowerCase().includes(value.trim().toLowerCase())).slice(0,6);const canCreate=!(key==='affiliations'&&invalidOrganizationAffiliation(value,currentChipModel()))&&!spec.existingOnly&&value.trim()&&!selected.includes(value.trim())&&!matches.some(e=>e.id===value.trim()||title(e)===value.trim());area.innerHTML=matches.map(e=>`<button type="button" role="option" aria-selected="false" data-action="add-chip" data-field="${key}" data-value="${esc(e.id)}">${esc(title(e))}<small>登録済み</small></button>`).join('')+(canCreate?`<button type="button" role="option" aria-selected="false" class="suggestion-new" data-action="add-chip" data-field="${key}" data-value="${esc(value.trim())}">＋「${esc(value.trim())}」を追加<small>保存時に新規登録</small></button>`:'');area.hidden=!area.innerHTML;$('chip-'+key).setAttribute('aria-expanded',String(!area.hidden));}
function capture(){if(!editor||!$('activity-form'))return;document.querySelectorAll('#activity-form [data-key]').forEach(input=>editor[input.dataset.key]=input.dataset.key==='external_links'?input.value.split('\n').map(v=>v.trim()).filter(Boolean):input.value);editor.participants=[...document.querySelectorAll('[data-member]')].map(row=>Object.fromEntries([...row.querySelectorAll('[data-member-key]')].map(input=>[input.dataset.memberKey,input.value])));document.querySelectorAll('#activity-form [data-chip-input]').forEach(input=>editor._pending[input.dataset.chipInput]=input.value);}
function persist(){if($('profile-dialog').open)return;if($('article-form')){persistArticle();return;}if(!editor||!$('activity-form'))return;capture();editor._updated=Date.now();const all=drafts();all[editor.entity_id||'new']=editor;const ok=storage.set('ritou-activity-drafts:'+personId,all);$('draft-state').innerHTML=icon(ok?'check':'file')+(ok?'このブラウザに下書きを保存しました':'下書きを保存できません。画面を閉じる前に保存してください');updatePreview();}
function previewHtml(){const e=editor;return `<article class="panel preview-card"><div class="preview-strip"></div><div class="preview-content"><p class="category-label">研究・活動</p><h3 style="margin-top:12px">${esc(e.title||'研究・活動の名称が入ります')}</h3><p class="preview-summary">${esc(e.summary||'取り組みの概要がここに表示されます。')}</p><div class="tags">${e.issues.slice(0,2).map(v=>`<span class="tag issue">${esc(title(entity(v))||v)}</span>`).join('')}${e.technologies.slice(0,3).map(v=>`<span class="tag">${esc(title(entity(v))||v)}</span>`).join('')}</div><div class="preview-divider"></div>${e.period?`<div class="preview-item">${icon('calendar')}<span>${esc(e.period)}</span></div>`:''}<div class="preview-item">${icon('pin')}<span>${esc(e.targets.map(v=>title(entity(v))||v).join('・')||'地域・現場は未設定')}</span></div><div class="preview-item">${icon('users')}<span>${esc(e.participants.filter(p=>p.name.trim()).map(p=>title(entity(p.name))||p.name).join('・')||'メンバーは未設定')}</span></div></div></article>`;}
function updatePreview(){if(!editor||!$('live-preview'))return;updateActivityOverviewPreview();$('live-preview').innerHTML=previewHtml();if($('summary-count'))$('summary-count').textContent=editor.summary.length+'文字';}
function flushPending(){capture();for(const [key,value] of Object.entries(editor._pending)){if(chipSpecs[key]&&value.trim()){editor[key]=uniq([...editor[key],...split(value)]);editor._pending[key]='';}}}
async function saveActivity(event){event.preventDefault();if(saving)return;flushPending();if(!editor.entity_id&&!editor._new_id)editor._new_id='research_'+crypto.randomUUID().replaceAll('-','').slice(0,16);const draftKey=editor.entity_id||'new';const payload={...editor,entity_id:editor.entity_id||editor._new_id,participants:editor.participants.filter(p=>p.name.trim())};for(const key of Object.keys(payload))if(key.startsWith('_'))delete payload[key];persist();saving=true;$('save-activity').disabled=true;$('save-activity').textContent='保存しています…';$('activity-error').hidden=true;try{const result=await request('/api/portfolio/activity',payload);deleteDraft(draftKey);editor=null;location.hash=activityHref(result.entity_id);await load();renderActivity(result.entity_id);window.scrollTo({top:0});notify('研究・活動を保存しました');}catch(error){if(!$('activity-error')){notify('保存処理の後に画面を更新できませんでした。再読み込みで確認してください。');return;}$('activity-error').textContent=error.message;$('activity-error').hidden=false;$('activity-error').scrollIntoView({behavior:'smooth',block:'center'});$('save-activity').disabled=false;$('save-activity').innerHTML='保存して反映する '+icon('check');persist();}finally{saving=false;}}
function openProfile(id){const e=entity(id);profileDraft={entity_id:id,display_name:literal(e,'表示名')||id,headline:literal(e,'肩書'),summary:literal(e,'概要'),description:e.wiki_content||'',affiliations:out(e,'所属する'),statuses:out(e,'である'),keywords:split(literal(e,'研究キーワード')),external_links:out(e,'外部リンク'),_pending:{}};const p=profileDraft;$('profile-dialog-content').innerHTML=`<form id="profile-form"><div class="dialog-header"><h2 id="profile-dialog-title">プロフィールを編集</h2><button type="button" class="icon-button" data-action="close-profile" aria-label="閉じる">×</button></div><div class="dialog-body"><div id="profile-error" class="form-error" hidden role="alert"></div><div class="two-fields"><div class="field"><label for="profile-name">表示名</label><input id="profile-name" data-profile-key="display_name" value="${esc(p.display_name)}" required></div><div class="field"><label for="profile-headline">肩書・専門</label><input id="profile-headline" data-profile-key="headline" value="${esc(p.headline)}" placeholder="例：情報工学科・地域連携担当"></div></div>${chipField('affiliations',p)}${chipField('statuses',p)}${chipField('keywords',p)}<div class="field"><label for="profile-summary">短い自己紹介</label><textarea id="profile-summary" data-profile-key="summary" rows="3">${esc(p.summary)}</textarea></div><div class="field"><label for="profile-description">詳しいプロフィール</label><textarea id="profile-description" data-profile-key="description" rows="5">${esc(p.description)}</textarea></div><div class="field"><label for="profile-links">関連リンク（1行に1件）</label><textarea id="profile-links" data-profile-key="external_links" rows="2" placeholder="https://...">${esc(p.external_links.join('\n'))}</textarea></div></div><div class="dialog-actions"><button class="button" type="button" data-action="close-profile">キャンセル</button><button class="button primary" type="submit" id="save-profile">保存する</button></div></form>`;$('profile-dialog').showModal();}
async function saveProfile(event){event.preventDefault();const p={...profileDraft};document.querySelectorAll('[data-profile-key]').forEach(input=>p[input.dataset.profileKey]=input.dataset.profileKey==='external_links'?input.value.split('\n').map(v=>v.trim()).filter(Boolean):input.value);for(const key of ['affiliations','statuses','keywords']){const pending=$('chip-'+key)?.value||'';p[key]=uniq([...p[key],...split(pending)]);}delete p._pending;$('save-profile').disabled=true;try{await request('/api/portfolio/profile',p);$('profile-dialog').close();await load();route();notify('プロフィールを保存しました');}catch(error){$('profile-error').textContent=error.message;$('profile-error').hidden=false;$('profile-error').scrollIntoView();$('save-profile').disabled=false;}}
function route(){issuePageToken++;destroyIssueMap();const [hash,query='']=(location.hash.slice(1)||'articles').split('?');let [view,...ids]=hash.split('/');let id;try{id=decodeURIComponent(ids.join('/'));}catch{return notFound();}if(view!=='editor')editor=null;if(view==='organizations'){search=new URLSearchParams(query).get('q')||'';renderOrganizations();}else if(view==='portfolio')renderPortfolio();else if(view==='person')renderPortfolio(id);else if(['activities','people','articles','explore'].includes(view)){search=new URLSearchParams(query).get('q')||'';filter='all';renderList(view);}else if(view==='issues')renderIssues(id);else if(view==='issue')renderIssue(id);else if(view==='place-new')renderPlaceEditor();else if(view==='place-edit')renderPlaceEditor(id);else if(view==='issue-new')renderIssueEditor();else if(view==='issue-edit')renderIssueEditor(id);else if(view==='ai')renderIslandAI(id);else if(view==='activity')renderActivity(id);else if(view==='editor')renderEditor();else if(view==='entity')renderEntity(id);else if(view==='article')renderArticle(id);else if(view==='article-edit')renderArticleEditor(id);else if(view==='article-new')renderArticleEditor('','news');else if(view==='activity-record')renderArticleEditor('','portfolio',id);else if(view==='research-news')renderArticleEditor('','news',id);else if(view==='research-note')renderArticleEditor('','research',id);else notFound();window.scrollTo({top:0});}

function updateActivityOverviewPreview(){const pane=$('activity-overview-preview');if(pane&&editor)pane.innerHTML=editor.description.trim()?articleMarkdown(editor.description):'<p class="muted">本文を入力すると、ここに表示されます。</p>';}
function setActivityOverviewView(view){capture();const preview=view==='preview';updateActivityOverviewPreview();$('activity-overview-write-pane').hidden=preview;$('activity-overview-preview').hidden=!preview;$('activity-overview-write-tab').setAttribute('aria-selected',String(!preview));$('activity-overview-preview-tab').setAttribute('aria-selected',String(preview));}
function activityOverviewRelatedItems(){return uniq([...(editor?.targets||[]),...(editor?.issues||[]),...(editor?.technologies||[]),...(editor?.resources||[]),...(editor?.participants||[]).map(p=>p.name)]).map(entity).filter(Boolean);}
function showActivityOverviewRelated(){capture();const panel=$('activity-overview-related');panel.hidden=!panel.hidden;document.querySelector('[data-overview-related]')?.setAttribute('aria-expanded',String(!panel.hidden));const items=activityOverviewRelatedItems();panel.innerHTML='<p class="hint">上で選択した登録済みの地域・課題・技術・人などを、本文から参照できます。</p>'+items.map(e=>`<button class="button small" type="button" data-overview-link="${esc(e.id)}">${esc(title(e))}</button>`).join('')+(items.length?'':'<p class="hint">関連項目を上の入力欄で選ぶと、ここに表示されます。</p>');}
function insertActivityOverviewLink(id){const e=entity(id),input=$('activity-description');if(!e||!input)return;const label=title(e).replace(/[\\[\]]/g,'\\$&'),href=e.types.includes('Research')?activityHref(id):e.types.includes('User')?personHref(id):'#entity/'+encodeURIComponent(id);input.setRangeText('['+label+']('+href+')',input.selectionStart,input.selectionEnd,'end');input.focus();persist();}
document.addEventListener('click',event=>{const view=event.target.closest('[data-overview-view]');if(view)setActivityOverviewView(view.dataset.overviewView);const format=event.target.closest('[data-overview-format]');if(format)insertMarkdownFormat($('activity-description'),format.dataset.overviewFormat,persist);if(event.target.closest('[data-overview-related]'))showActivityOverviewRelated();const link=event.target.closest('[data-overview-link]');if(link)insertActivityOverviewLink(link.dataset.overviewLink);});
document.addEventListener('keydown',event=>{if(event.target.id!=='activity-description'||!(event.metaKey||event.ctrlKey)||event.isComposing)return;const format={b:'bold',i:'italic',k:'link'}[event.key.toLowerCase()];if(format){event.preventDefault();insertMarkdownFormat(event.target,format,persist);}});
// イベントは委譲して、画面を切り替えても二重登録しない。
document.addEventListener('click',event=>{const button=event.target.closest('[data-action]');if(!button){if(!event.target.closest('.chip-entry'))document.querySelectorAll('.suggestions').forEach(s=>{s.hidden=true;const input=s.parentElement.querySelector('input');input?.setAttribute('aria-expanded','false');});return;}const action=button.dataset.action;if(action==='new-organization')openOrganizationEditor();else if(action==='edit-organization')openOrganizationEditor(button.dataset.id);else if(action==='new-activity')startEditor();else if(action==='edit-activity')startEditor(button.dataset.id);else if(action==='resume-draft')startEditor('',true);else if(action==='discard-draft'){const draft=latestDraft();if(draft){storage.set('ritou-discarded-draft:'+personId,draft);deleteDraft(draft.entity_id||'new');}renderPortfolio();notify('下書きを削除しました（直前の1件は「下書きを復元」から戻せます）');}else if(action==='restore-draft'){const draft=storage.get('ritou-discarded-draft:'+personId);if(draft){const all=drafts();all[draft.entity_id||'new']=draft;storage.set('ritou-activity-drafts:'+personId,all);storage.remove('ritou-discarded-draft:'+personId);renderPortfolio();}}else if(action==='portfolio-tab'){portfolioTab=button.dataset.value;const id=location.hash.startsWith('#person/')?decodeURIComponent(location.hash.slice(8)):personId;renderPortfolio(id);}else if(action==='edit-organization-affiliations')openOrganizationAffiliations(button.dataset.id);else if(action==='edit-profile')openProfile(button.dataset.id);else if(action==='close-profile')$('profile-dialog').close();else if(action==='filter'){filter=button.dataset.value;document.querySelectorAll('.filter').forEach(b=>b.classList.toggle('active',b.dataset.value===filter));renderListResults('explore');}else if(action==='add-chip')addChips(button.dataset.field,button.dataset.value);else if(action==='remove-chip'){const key=button.dataset.field;currentChipModel()[key].splice(Number(button.dataset.index),1);refreshChips(key);}else if(action==='add-member'){capture();editor.participants.push({name:'',role:'担当',actor_class:'User'});$('member-rows').innerHTML=editor.participants.map(memberMarkup).join('');$('member-rows').lastElementChild.querySelector('input').focus();persist();}else if(action==='remove-member'){capture();editor.participants.splice(Number(button.dataset.index),1);$('member-rows').innerHTML=editor.participants.map(memberMarkup).join('');persist();}else if(action==='preview-activity'){capture();const content=`<div class="dialog-header"><h2 id="profile-dialog-title">掲載内容のプレビュー</h2><button type="button" class="icon-button" data-action="close-profile" aria-label="閉じる">×</button></div><div class="dialog-body">${previewHtml()}${editor.goal?`<div class="field lab-section"><h3>目指していること</h3><p class="prose">${esc(editor.goal)}</p></div>`:''}${editor.description?`<div class="prose lab-section">${prose(editor.description)}</div>`:''}<p class="hint">まだデータベースには保存されていません。</p></div>`;$('profile-dialog-content').innerHTML=content;$('profile-dialog').showModal();}});
document.addEventListener('input',event=>{const el=event.target;if(el.matches('[data-chip-input]')){const key=el.dataset.chipInput;currentChipModel()._pending[key]=el.value;suggest(key,el.value);}if(el.closest('#activity-form')||el.closest('#article-form'))persist();if(el.id==='organization-summary')$('organization-summary-preview').innerHTML=articleMarkdown(el.value);if(el.id==='organization-search'){search=el.value;const cursor=el.selectionStart;renderOrganizations();const input=$('organization-search');input.focus();if(cursor!==null)input.setSelectionRange(cursor,cursor);}if(el.id==='list-search'){search=el.value;renderListResults(location.hash.slice(1)||'articles');}});
document.addEventListener('focusin',event=>{if(event.target.matches('[data-chip-input]'))suggest(event.target.dataset.chipInput,event.target.value);});
document.addEventListener('keydown',event=>{const el=event.target;if(el.matches('[data-chip-input]')){if(event.isComposing||event.keyCode===229)return;if(event.key==='Enter'){event.preventDefault();addChips(el.dataset.chipInput,el.value);}else if(event.key==='Escape'){const area=$('suggest-'+el.dataset.chipInput);area.hidden=true;el.setAttribute('aria-expanded','false');}else if(event.key==='ArrowDown'){event.preventDefault();$('suggest-'+el.dataset.chipInput).querySelector('button')?.focus();}}});
document.addEventListener('change',event=>{if(event.target.closest('#activity-form')||event.target.closest('#article-form'))persist();if(event.target.matches('[data-member-key="name"]')){const row=event.target.closest('[data-member]');const found=entity(event.target.value);const kind=found?.types.find(t=>['User','Laboratory','ActorGroup'].includes(t));if(kind)row.querySelector('[data-member-key="actor_class"]').value=kind;persist();}});
document.addEventListener('submit',event=>{if(event.target.id==='activity-form')saveActivity(event);if(event.target.id==='profile-form')saveProfile(event);if(event.target.id==='organization-affiliations-form')saveOrganizationAffiliations(event);if(event.target.id==='organization-form')saveOrganization(event);});
