paintIcons();document.addEventListener('DOMContentLoaded',()=>{load().then(route).catch(error=>setPage('読み込みエラー',`<div class="page"><div class="form-error">${esc(error.message)}</div><button class="button" onclick="location.reload()">再読み込み</button></div>`));});
